/*

 Foxtrot Sigma-9 Theme
 [2022 Wikidot Theme]
 By Liryn

*/

/* FONTS */

@import url('https://fonts.bunny.net/css2?family=Montserrat:ital,wght@0,800;1,800&display=swap');

@import url('https://fonts.bunny.net/css2?family=Lexend:wght@700;800&display=swap');

